import React, { useState, useEffect } from 'react';
import { adminApi } from '../api/admin';
import { RefundRecord, Pagination } from '../types';
import { useAuth } from '../context/AuthContext';
import { useShop } from '../context/ShopContext';
import {
  RotateCcw,
  CheckCircle2,
  XCircle,
  Play,
  AlertTriangle,
  RefreshCw,
  Loader2,
  EyeOff,
  Filter,
  Info,
} from 'lucide-react';

export const AdminRefunds: React.FC = () => {
  const { user, hasRole } = useAuth();
  const { formatPrice } = useShop();

  const isFinance = hasRole(['admin', 'super_admin', 'finance']);

  const [refunds, setRefunds] = useState<RefundRecord[]>([]);
  const [pagination, setPagination] = useState<Pagination>({
    page: 1,
    limit: 25,
    total: 0,
    totalPages: 1,
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);

  const [statusFilter, setStatusFilter] = useState('');
  const [activeActionId, setActiveActionId] = useState<string | null>(null);

  const fetchRefunds = async (targetPage = 1) => {
    setLoading(true);
    setError(null);
    try {
      const res = await adminApi.getRefunds({
        page: targetPage,
        limit: pagination.limit,
        status: statusFilter || undefined,
      });
      setRefunds(res.refunds);
      setPagination(res.pagination);
    } catch (err: any) {
      setError(err?.error || err?.message || 'Could not load refund records.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRefunds(1);
  }, [statusFilter]);

  const [transitionModal, setTransitionModal] = useState<{
    refundId: string;
    action: 'approve' | 'process' | 'fail' | 'cancel' | 'settle-manual';
    title: string;
    description: string;
    requiresReason: boolean;
  } | null>(null);
  const [transitionReason, setTransitionReason] = useState('');
  const [transitionApprovedAmount, setTransitionApprovedAmount] = useState('');
  const [submittingTransition, setSubmittingTransition] = useState(false);
  const [transitionError, setTransitionError] = useState<string | null>(null);

  const openTransitionModal = (
    refundId: string,
    action: 'approve' | 'process' | 'fail' | 'cancel' | 'settle-manual',
    title: string,
    description: string,
    requiresReason = false
  ) => {
    setTransitionModal({ refundId, action, title, description, requiresReason });
    setTransitionReason('');
    setTransitionApprovedAmount('');
    setTransitionError(null);
  };

  const handleExecuteTransition = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!transitionModal) return;

    if (transitionModal.requiresReason && !transitionReason.trim()) {
      setTransitionError('A justification reason is required for this transition.');
      return;
    }

    setSubmittingTransition(true);
    setTransitionError(null);
    try {
      const { refundId, action } = transitionModal;
      if (action === 'approve') {
        const approvedAmount = transitionApprovedAmount ? parseInt(transitionApprovedAmount, 10) : undefined;
        await adminApi.approveRefund(refundId, { reason: transitionReason.trim() || undefined, approvedAmount });
        setActionSuccess(`Refund #${refundId} approved.`);
      } else if (action === 'process') {
        await adminApi.processRefund(refundId, transitionReason.trim() || 'Processing financial payout');
        setActionSuccess(`Refund #${refundId} moved to PROCESSING.`);
      } else if (action === 'fail') {
        await adminApi.failRefund(refundId, transitionReason.trim() || 'Gateway processing error');
        setActionSuccess(`Refund #${refundId} marked as FAILED.`);
      } else if (action === 'cancel') {
        await adminApi.cancelRefund(refundId, transitionReason.trim() || 'Cancelled by staff');
        setActionSuccess(`Refund #${refundId} CANCELLED.`);
      } else if (action === 'settle-manual') {
        await adminApi.settleManualRefund(refundId, transitionReason.trim());
        setActionSuccess(`Refund #${refundId} manually settled (providerConfirmed: false).`);
      }

      setTransitionModal(null);
      await fetchRefunds(pagination.page);
    } catch (err: any) {
      setTransitionError(err?.error || err?.message || 'Failed to execute refund transition.');
    } finally {
      setSubmittingTransition(false);
    }
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8 pb-6 border-b border-slate-200 dark:border-slate-800">
        <div>
          <div className="flex items-center gap-2">
            <span className="text-[11px] font-mono uppercase tracking-wider text-purple-600 dark:text-purple-400 font-bold">
              FINANCIAL RESOLUTION
            </span>
            <span className="px-2 py-0.5 rounded-full text-[10px] font-semibold bg-purple-500/10 text-purple-600 dark:text-purple-400 border border-purple-500/20 font-mono">
              {isFinance ? 'Finance Privileged Role' : 'Staff Read-Only Redacted'}
            </span>
          </div>
          <h1 className="font-display text-2xl sm:text-3xl font-bold text-slate-900 dark:text-white mt-1">
            Refunds Workflow Queue
          </h1>
          <p className="text-xs sm:text-sm text-slate-500 dark:text-slate-400 mt-1">
            Manage refund requests, approve reserved balances, and record settlement state transitions.
          </p>
        </div>

        <button
          type="button"
          onClick={() => fetchRefunds(pagination.page)}
          disabled={loading}
          className="self-start sm:self-auto px-3.5 py-2 rounded-xl border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-900 text-xs font-semibold text-slate-700 dark:text-slate-300 inline-flex items-center gap-1.5 transition-colors"
        >
          <RefreshCw size={13} className={loading ? 'animate-spin' : ''} />
          <span>Refresh</span>
        </button>
      </div>

      {actionSuccess && (
        <div className="p-4 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-600 dark:text-emerald-400 text-xs mb-6 flex items-start gap-2.5">
          <CheckCircle2 size={16} className="shrink-0 mt-0.5" />
          <span>{actionSuccess}</span>
        </div>
      )}

      {/* Filter toolbar */}
      <div className="p-4 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm mb-6 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Filter size={14} className="text-slate-400" />
          <select
            value={statusFilter}
            onChange={e => setStatusFilter(e.target.value)}
            className="px-3 py-1.5 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs font-mono text-slate-900 dark:text-white focus:outline-none"
          >
            <option value="">All Statuses</option>
            <option value="REQUESTED">REQUESTED</option>
            <option value="APPROVED">APPROVED</option>
            <option value="PROCESSING">PROCESSING</option>
            <option value="COMPLETED">COMPLETED</option>
            <option value="FAILED">FAILED</option>
            <option value="CANCELLED">CANCELLED</option>
          </select>
        </div>

        <span className="text-xs font-mono text-slate-400">
          Showing {refunds.length} record{refunds.length === 1 ? '' : 's'}
        </span>
      </div>

      {loading ? (
        <div className="flex flex-col items-center justify-center py-20 text-slate-400">
          <Loader2 size={32} className="animate-spin text-purple-500 mb-3" />
          <span className="text-xs font-mono">Loading refunds ledger...</span>
        </div>
      ) : error ? (
        <div className="p-8 rounded-2xl bg-rose-500/10 border border-rose-500/20 text-center max-w-md mx-auto">
          <AlertTriangle size={28} className="text-rose-500 mx-auto mb-3" />
          <h2 className="font-display text-base font-bold text-slate-900 dark:text-white mb-1">
            Could Not Load Refunds
          </h2>
          <p className="text-xs text-slate-500 dark:text-slate-400 mb-4">{error}</p>
          <button
            type="button"
            onClick={() => fetchRefunds(1)}
            className="px-4 py-2 bg-purple-600 text-white rounded-lg text-xs font-semibold"
          >
            Retry
          </button>
        </div>
      ) : refunds.length === 0 ? (
        <div className="p-12 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 text-center max-w-md mx-auto">
          <RotateCcw size={28} className="text-slate-400 mx-auto mb-3" />
          <h2 className="font-display text-lg font-bold text-slate-900 dark:text-white mb-1">
            No Refunds Found
          </h2>
          <p className="text-xs text-slate-500 dark:text-slate-400">
            No refund records match the specified filters.
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          {refunds.map(refund => {
            const isProcessingAction = activeActionId === refund.refundId;
            const canTransition = isFinance && !isProcessingAction;

            return (
              <div
                key={refund.refundId}
                className="p-6 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col lg:flex-row lg:items-center justify-between gap-6"
              >
                <div className="space-y-1.5">
                  <div className="flex flex-wrap items-center gap-2.5">
                    <span className="font-mono text-xs font-bold text-slate-900 dark:text-white">
                      #{refund.refundId}
                    </span>
                    <span className="px-2 py-0.5 rounded text-[10px] font-mono font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300">
                      {refund.status}
                    </span>
                    <span className="text-[11px] font-mono text-slate-400">
                      (Order #{refund.orderId})
                    </span>
                  </div>

                  <div className="text-xs text-slate-500 dark:text-slate-400 font-mono">
                    Requested {new Date(refund.requestedAt).toLocaleString()}
                    {refund.reason && <span className="ml-2 italic">— "{refund.reason}"</span>}
                  </div>
                </div>

                <div className="flex flex-wrap items-center justify-between lg:justify-end gap-6 pt-4 lg:pt-0 border-t lg:border-t-0 border-slate-100 dark:border-slate-800">
                  <div className="text-left lg:text-right">
                    <div className="text-[10px] uppercase font-mono tracking-wider text-slate-400">
                      Amount
                    </div>
                    {refund.amount !== undefined || refund.requestedAmount !== undefined ? (
                      <div className="font-mono text-sm font-bold text-purple-600 dark:text-purple-400">
                        {formatPrice(
                          refund.refundedAmount || refund.approvedAmount || refund.requestedAmount || refund.amount || 0,
                          refund.currency
                        )}
                      </div>
                    ) : (
                      <div className="flex items-center gap-1 text-slate-400 text-xs font-mono">
                        <EyeOff size={12} />
                        <span>[Redacted]</span>
                      </div>
                    )}
                  </div>

                  {/* State transition buttons for finance roles */}
                  {canTransition && (
                    <div className="flex flex-wrap items-center gap-2">
                      {refund.status === 'REQUESTED' && (
                        <>
                          <button
                            type="button"
                            onClick={() =>
                              openTransitionModal(
                                refund.refundId,
                                'approve',
                                'Approve Refund Request',
                                `Approve customer refund #${refund.refundId}. An optional approved amount can be set up to the reserved limit.`
                              )
                            }
                            className="px-3 py-1.5 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold"
                          >
                            Approve
                          </button>
                          <button
                            type="button"
                            onClick={() =>
                              openTransitionModal(
                                refund.refundId,
                                'cancel',
                                'Cancel Refund Request',
                                `Cancel refund #${refund.refundId}. The reserved balance will be released back to the order.`,
                                true
                              )
                            }
                            className="px-3 py-1.5 rounded-lg border border-rose-300 dark:border-rose-900/60 text-rose-600 dark:text-rose-400 text-xs font-semibold hover:bg-rose-500/10"
                          >
                            Cancel
                          </button>
                        </>
                      )}

                      {refund.status === 'APPROVED' && (
                        <>
                          <button
                            type="button"
                            onClick={() =>
                              openTransitionModal(
                                refund.refundId,
                                'process',
                                'Mark Refund as Processing',
                                `Move refund #${refund.refundId} into PROCESSING queue for payment gateway disbursement.`
                              )
                            }
                            className="px-3 py-1.5 rounded-lg bg-blue-600 hover:bg-blue-500 text-white text-xs font-semibold"
                          >
                            Mark Processing
                          </button>
                          <button
                            type="button"
                            onClick={() =>
                              openTransitionModal(
                                refund.refundId,
                                'cancel',
                                'Cancel Approved Refund',
                                `Cancel refund #${refund.refundId} before disbursement begins.`,
                                true
                              )
                            }
                            className="px-3 py-1.5 rounded-lg border border-rose-300 dark:border-rose-900/60 text-rose-600 dark:text-rose-400 text-xs font-semibold hover:bg-rose-500/10"
                          >
                            Cancel
                          </button>
                        </>
                      )}

                      {refund.status === 'PROCESSING' && (
                        <>
                          <button
                            type="button"
                            onClick={() =>
                              openTransitionModal(
                                refund.refundId,
                                'settle-manual',
                                'Execute Manual Settlement',
                                `Manually mark refund #${refund.refundId} as settled. Note: this flags providerConfirmed: false as it represents an offline/manual settlement rather than direct gateway confirmation.`,
                                true
                              )
                            }
                            className="px-3 py-1.5 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold"
                          >
                            Manual Settle
                          </button>
                          <button
                            type="button"
                            onClick={() =>
                              openTransitionModal(
                                refund.refundId,
                                'fail',
                                'Mark Refund as Failed',
                                `Mark refund #${refund.refundId} as FAILED and release reserved balance.`,
                                true
                              )
                            }
                            className="px-3 py-1.5 rounded-lg bg-amber-600 hover:bg-amber-500 text-white text-xs font-semibold"
                          >
                            Mark Failed
                          </button>
                          <button
                            type="button"
                            onClick={() =>
                              openTransitionModal(
                                refund.refundId,
                                'cancel',
                                'Cancel Processing Refund',
                                `Cancel refund #${refund.refundId} during processing.`,
                                true
                              )
                            }
                            className="px-3 py-1.5 rounded-lg border border-rose-300 dark:border-rose-900/60 text-rose-600 dark:text-rose-400 text-xs font-semibold hover:bg-rose-500/10"
                          >
                            Cancel
                          </button>
                        </>
                      )}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Transition Modal */}
      {transitionModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs">
          <div className="w-full max-w-md bg-white dark:bg-[#121418] rounded-3xl border border-slate-200 dark:border-slate-800 shadow-2xl p-6 sm:p-8">
            <div className="flex items-center justify-between pb-4 border-b border-slate-100 dark:border-slate-800">
              <h3 className="font-display text-lg font-bold text-slate-900 dark:text-white">
                {transitionModal.title}
              </h3>
              <button
                type="button"
                onClick={() => setTransitionModal(null)}
                className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"
              >
                <XCircle size={18} />
              </button>
            </div>

            {transitionError && (
              <div className="mt-4 p-3 rounded-xl bg-rose-500/10 border border-rose-500/20 text-rose-600 dark:text-rose-400 text-xs flex items-center gap-2">
                <AlertTriangle size={14} />
                <span>{transitionError}</span>
              </div>
            )}

            <form onSubmit={handleExecuteTransition} className="mt-6 space-y-4">
              <p className="text-xs text-slate-600 dark:text-slate-300 leading-relaxed">
                {transitionModal.description}
              </p>

              {transitionModal.action === 'approve' && (
                <div>
                  <label className="block text-[11px] font-semibold text-slate-600 dark:text-slate-400 uppercase tracking-wider mb-1">
                    Approved Amount (Optional Override)
                  </label>
                  <input
                    type="number"
                    min={1}
                    value={transitionApprovedAmount}
                    onChange={e => setTransitionApprovedAmount(e.target.value)}
                    placeholder="Leave empty for full requested amount"
                    className="w-full px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white font-mono"
                  />
                </div>
              )}

              <div>
                <label className="block text-[11px] font-semibold text-slate-600 dark:text-slate-400 uppercase tracking-wider mb-1">
                  Reason / Internal Note {transitionModal.requiresReason && '*'}
                </label>
                <textarea
                  required={transitionModal.requiresReason}
                  value={transitionReason}
                  onChange={e => setTransitionReason(e.target.value)}
                  rows={2}
                  placeholder="Justification for state change..."
                  className="w-full px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white"
                />
              </div>

              <div className="flex items-center justify-end gap-3 pt-4 border-t border-slate-100 dark:border-slate-800">
                <button
                  type="button"
                  onClick={() => setTransitionModal(null)}
                  disabled={submittingTransition}
                  className="px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-800 text-xs font-semibold text-slate-600 dark:text-slate-300"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={submittingTransition}
                  className="px-5 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-semibold inline-flex items-center gap-1.5 transition-colors disabled:opacity-50"
                >
                  {submittingTransition && <Loader2 size={13} className="animate-spin" />}
                  <span>Confirm Transition</span>
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminRefunds;
